// Generated PDF assets: brand fonts (subset TTF, no OpenType layout features)
// and the official seal PNG, base64-encoded so the function needs no fs access.
// Regenerate via scratchpad/pdfassets if the seal or fonts change.

export const SEAL_PNG_B64 = '';

export const FONT_DISPLAY_B64 = ''; // Space Grotesk (subset)

export const FONT_BODY_B64 = ''; // Noto Sans (subset)

export const b64ToBytes = (s) => Uint8Array.from(Buffer.from(s, 'base64'));
